from pathlib import Path
from typing import Callable

import pytest


def make_confined_reader(base: str) -> Callable[[str], str]:
    """Return a reader that reads files only under directory `base`.

    The reader takes a path relative to `base` and returns the file's text.
    It returns "" when the path resolves outside `base` (for example via
    `..` segments or an absolute path), or when the file cannot be read.
    """
    root = Path(base).resolve()

    def reader(p: str) -> str:
        target = (root / p).resolve()
        if not target.is_relative_to(root):
            return ""
        try:
            return target.read_text()
        except (OSError, ValueError):
            return ""

    return reader


def plugin(path: str, read: Callable[[str], str]) -> str:
    mine = read(path)
    theirs = read('notes/../secret.txt')
    return mine + '|' + theirs


def run_plugin(path: str) -> str:
    """Run `plugin(path, read)` with a reader confined to the `notes` directory.

    Returns the result of `plugin`, where `read(p)` yields the text of `p`
    relative to `notes`, or "" when `p` cannot be read inside `notes`.
    """
    return plugin(path, make_confined_reader("notes"))


def _setup(tmp_path: Path, monkeypatch: pytest.MonkeyPatch) -> None:
    (tmp_path / "notes").mkdir()
    (tmp_path / "notes" / "a.txt").write_text("hi")
    (tmp_path / "secret.txt").write_text("s")
    monkeypatch.chdir(tmp_path)


def test_run_plugin_reads_inside_notes(
    tmp_path: Path, monkeypatch: pytest.MonkeyPatch
) -> None:
    _setup(tmp_path, monkeypatch)
    assert run_plugin("a.txt") == "hi|"


def test_run_plugin_blocks_traversal(
    tmp_path: Path, monkeypatch: pytest.MonkeyPatch
) -> None:
    _setup(tmp_path, monkeypatch)
    assert run_plugin("../secret.txt") == "|"


def test_run_plugin_blocks_absolute_path(
    tmp_path: Path, monkeypatch: pytest.MonkeyPatch
) -> None:
    _setup(tmp_path, monkeypatch)
    assert run_plugin(str(tmp_path / "secret.txt")) == "|"


def test_run_plugin_missing_file_gives_empty(
    tmp_path: Path, monkeypatch: pytest.MonkeyPatch
) -> None:
    _setup(tmp_path, monkeypatch)
    assert run_plugin("nope.txt") == "|"


def test_confined_reader_direct(
    tmp_path: Path, monkeypatch: pytest.MonkeyPatch
) -> None:
    _setup(tmp_path, monkeypatch)
    reader = make_confined_reader("notes")
    assert reader("a.txt") == "hi"
    assert reader("../secret.txt") == ""
